from collections import OrderedDict

def cache_sim(capacity, ttl, ops):
    cache = OrderedDict()  # key -> (value, write_time)
    results = []

    def is_expired(key, t):
        if key not in cache:
            return True
        _, wtime = cache[key]
        return t >= wtime + ttl

    for op in ops:
        if op[0] == 'put':
            _, t, key, value = op
            if key in cache:
                if is_expired(key, t):
                    del cache[key]
            if key in cache:
                cache[key] = (value, t)
                cache.move_to_end(key)
            else:
                if len(cache) >= capacity:
                    # evict least recently used, but need to consider only if it's truly full of valid entries
                    # standard LRU eviction: remove oldest inserted (first in OrderedDict)
                    cache.popitem(last=False)
                cache[key] = (value, t)
                cache.move_to_end(key)
        elif op[0] == 'get':
            _, t, key = op
            if key in cache and not is_expired(key, t):
                value, wtime = cache[key]
                cache.move_to_end(key)
                results.append(value)
            else:
                if key in cache:
                    del cache[key]
                results.append(-1)

    return results

